    return gcd(a, gcd(b, c))

def is_good_set(U):
    if len(U) < 3:
        return False

    # Condition 2: gcd of any three distinct elements is 1
    for triple in combinations(U, 3):
        if gcd_three(*triple) != 1:
            return False

    # Condition 3: For any two distinct elements, there exists a third element that divides their product
    elements = list(U)
    for i in range(len(elements)):
